        Certificate = certificate,
    };

    public static CertificateChoices FromExtendedCertificate(ExtendedCertificate extendedCertificate) => new CertificateChoices
    {
        Kind = CertificateChoicesKind.ExtendedCertificate,
        ExtendedCertificate = extendedCertificate,
    };

    public static CertificateChoices FromOther(OtherCertificateFormat other) => new CertificateChoices
    {
        Kind = CertificateChoicesKind.Other,
        Other = other,
    };

    public override string ToString()
    {
        return Kind switch
        {
            CertificateChoicesKind.Certificate => Asn1Formatting.Format(Certificate),
            CertificateChoicesKind.ExtendedCertificate => Asn1Formatting.Format(ExtendedCertificate),
            CertificateChoicesKind.Other => Asn1Formatting.Format(Other),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case CertificateChoicesKind.Certificate:
                if (Certificate.HasEncoded)
                {
                    writer.WriteRaw(Certificate.EncodedMemory.Span);
                }
                else
                {
                    Certificate.Value.Encode(writer, Asn1Tag.Sequence);
                }
                break;
            case CertificateChoicesKind.ExtendedCertificate:
                ExtendedCertificate.Encode(writer, new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true));
                break;
            case CertificateChoicesKind.Other:
                Other.Encode(writer, new Asn1Tag(Asn1TagClass.ContextSpecific, 3, true));
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static CertificateChoices Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new CertificateChoices();
        if (peeked.MatchesIgnoreConstructed(Asn1Tag.Sequence))
        {
            value.Kind = CertificateChoicesKind.Certificate;
            value.Certificate = reader.ReadLazy(r =>
            {
                return Asn1Kit.Pkix.Certificate.Decode(r, Asn1Tag.Sequence);
            });
        }
        else if (peeked.MatchesIgnoreConstructed(new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true)))
        {
            value.Kind = CertificateChoicesKind.ExtendedCertificate;
            value.ExtendedCertificate = Asn1Kit.Cms.ExtendedCertificate.Decode(reader, new Asn1Tag(Asn1TagClass.ContextSpecific, 0, true));
        }
        else if (peeked.MatchesIgnoreConstructed(new Asn1Tag(Asn1TagClass.ContextSpecific, 3, true)))
        {
            value.Kind = CertificateChoicesKind.Other;
            value.Other = Asn1Kit.Cms.OtherCertificateFormat.Decode(reader, new Asn1Tag(Asn1TagClass.ContextSpecific, 3, true));
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

